    // =====================================================================
    // LESSON 10: At the Souk — Shopping Dialogue
    // Core vocab: بكم (how much), غالي (expensive), رخيص (cheap), أريد (I want), هذا/هذه
    //             المحل (shop), دنانير (dinars), أرخص (cheaper — comparative)
    // Pedagogy: INTRODUCE all key words first → COMPREHENSION → PRODUCTION
    // =====================================================================

