      questionAr: "تعلّم هذه الأفعال الأساسية (صيغة هو): كَتَبَ = he wrote، ذَهَبَ = he went، أَكَلَ = he ate، شَرِبَ = he drank. للمؤنث أضف ـتْ: كَتَبَتْ = she wrote. أيها تعني 'he went'؟",
      context: "Past tense verbs in Arabic are always learned in the هو (he) form first. This is the base form, like the infinitive in English. She (هي) = add ـتْ to the end.",
      contextAr: "الأفعال الماضية تُتعلم دائماً بصيغة هو أولاً. هذا هو الشكل الأساسي. هي = أضف ـتْ للنهاية",
      options: ["كَتَبَ (he wrote)", "ذَهَبَ (he went)", "أَكَلَ (he ate)", "شَرِبَ (he drank)"],
