      explanation: "ذَهَبَ (dhahaba) = he went. For 'she went': ذَهَبَتْ (add ـتْ). All four verbs follow the same فَعَلَ pattern: كَتَبَ, ذَهَبَ, أَكَلَ, شَرِبَ.",
      explanationAr: "ذَهَبَ = he went. 'هي ذهبت': ذَهَبَتْ (أضف ـتْ). جميع الأفعال الأربعة تتبع نمط فَعَلَ",
