      question: "Arabic is usually written WITHOUT vowel marks (like reading English without vowels). But when vowels ARE shown, they appear as small marks. The mark َ (a small diagonal above) is called فَتْحَة (fatha). What vowel sound does it make?",
      questionAr: "العربية تُكتب عادةً بدون حركات. لكن حين تُكتب الحركات تظهر كعلامات صغيرة. العلامة َ تسمى فَتْحَة. ما صوتها؟",
